@st.cache_data(ttl=600)
def charger_donnees():
    climat = pd.read_sql("SELECT * FROM vue_climat_complet", engine)
    mesures = pd.read_sql("SELECT * FROM vue_mesures_completes", engine)
    synthese = pd.read_sql("SELECT * FROM vue_synthese_essai", engine)
    sites = pd.read_sql("SELECT * FROM site", engine)
    varietes = pd.read_sql("SELECT * FROM variete", engine)
    essais = pd.read_sql("SELECT idexper, idsite FROM essai", engine)
    return climat, mesures, synthese, sites, varietes, essais

