with st.sidebar.expander("🔑 Changer mon mot de passe"):
    with st.form("form_changer_mdp"):
        ancien_mdp = st.text_input("Mot de passe actuel", type="password")
        nouveau_mdp = st.text_input("Nouveau mot de passe (8 caractères minimum)", type="password")
        confirmation_mdp = st.text_input("Confirmer le nouveau mot de passe", type="password")
        envoyer_mdp = st.form_submit_button("Changer le mot de passe")
    if envoyer_mdp:
        if hash_mdp(ancien_mdp, UTILISATEUR["sel"]) != UTILISATEUR["mot_de_passe_hash"]:
            st.error("Le mot de passe actuel est incorrect.")
        elif len(nouveau_mdp) < 8:
            st.error("Le nouveau mot de passe doit avoir au moins 8 caractères.")
        elif nouveau_mdp != confirmation_mdp:
            st.error("La confirmation ne correspond pas au nouveau mot de passe.")
        elif nouveau_mdp == ancien_mdp:
            st.error("Le nouveau mot de passe doit être différent de l'ancien.")
        else:
            nouveau_sel = secrets.token_hex(16)
            nouveau_hash = hash_mdp(nouveau_mdp, nouveau_sel)
            with engine.begin() as conn:
                conn.execute(
                    text("UPDATE utilisateur SET mot_de_passe_hash = :h, sel = :s WHERE idutilisateur = :id"),
                    {"h": nouveau_hash, "s": nouveau_sel, "id": int(UTILISATEUR["idutilisateur"])})
            UTILISATEUR["mot_de_passe_hash"] = nouveau_hash
            UTILISATEUR["sel"] = nouveau_sel
            st.success("Mot de passe modifié.")

