        @st.cache_resource
        def _init_historique():
            with engine.begin() as conn:
                conn.execute(text("""CREATE TABLE IF NOT EXISTS historique_import (
                    idimport SERIAL PRIMARY KEY,
                    date_import TIMESTAMP NOT NULL DEFAULT NOW(),
                    idutilisateur INTEGER,
                    utilisateur_nom TEXT,
                    type_import TEXT NOT NULL,
                    fichier TEXT,
                    cible TEXT,
                    statut TEXT NOT NULL DEFAULT 'actif',
                    date_annulation TIMESTAMP,
                    annule_par TEXT)"""))
                conn.execute(text("""CREATE TABLE IF NOT EXISTS historique_import_ligne (
                    idimport INTEGER NOT NULL REFERENCES historique_import(idimport) ON DELETE CASCADE,
                    nom_table TEXT NOT NULL,
                    cle TEXT NOT NULL)"""))
                conn.execute(text("CREATE INDEX IF NOT EXISTS idx_hist_ligne_import ON historique_import_ligne (idimport)"))
            return True

        _init_historique()

        _IMPORT = {"info": None, "id": None}
        ORDRE_SUPPRESSION = ["mesurephichi", "pointechanti", "msureclimat", "rendement"]
        CLES_PRIMAIRES = {"mesurephichi": "idmesure", "pointechanti": "idpoint",
                          "msureclimat": "idmesureclimat", "rendement": "idrendem"}

        def debut_import(type_import, fichier, cible):
            _IMPORT["info"] = (type_import, fichier, str(cible))
            _IMPORT["id"] = None

        def _id_import():
            if _IMPORT["info"] is None:
                return None
            if _IMPORT["id"] is None:
                type_i, fichier_i, cible_i = _IMPORT["info"]
                with engine.begin() as conn:
                    _IMPORT["id"] = conn.execute(
                        text("""INSERT INTO historique_import (idutilisateur, utilisateur_nom, type_import, fichier, cible)
                                VALUES (:u, :n, :t, :f, :c) RETURNING idimport"""),
                        {"u": int(UTILISATEUR["idutilisateur"]),
                         "n": f"{UTILISATEUR['prenom']} {UTILISATEUR['nom']}",
                         "t": type_i, "f": fichier_i, "c": cible_i}).scalar()
            return _IMPORT["id"]

        def noter_cles(table, cles):
            idi = _id_import()
            if idi is None or not cles:
                return
            with engine.begin() as conn:
                conn.execute(
                    text("INSERT INTO historique_import_ligne (idimport, nom_table, cle) VALUES (:i, :t, :c)"),
                    [{"i": idi, "t": table, "c": str(c)} for c in cles])

        def annuler_import(idimport, par):
            with engine.begin() as conn:
                lignes = conn.execute(
                    text("SELECT nom_table, cle FROM historique_import_ligne WHERE idimport = :i"),
                    {"i": idimport}).fetchall()
                par_table = {}
                for t, c in lignes:
                    par_table.setdefault(t, []).append(c)
                for t in ORDRE_SUPPRESSION:
                    if t in par_table:
                        conn.execute(
                            text(f"DELETE FROM {t} WHERE {CLES_PRIMAIRES[t]} = ANY(:cles)"),
                            {"cles": par_table[t]})
                conn.execute(
                    text("""UPDATE historique_import
                            SET statut = 'annule', date_annulation = NOW(), annule_par = :p
                            WHERE idimport = :i"""),
                    {"p": par, "i": idimport})

        @st.cache_resource
        def _init_journal():
            with engine.begin() as conn:
                conn.execute(text("""CREATE TABLE IF NOT EXISTS journal_creation (
                    idjournal SERIAL PRIMARY KEY,
                    date_creation TIMESTAMP NOT NULL DEFAULT NOW(),
                    idutilisateur INTEGER,
                    utilisateur_nom TEXT,
                    type_element TEXT NOT NULL,
                    code TEXT,
                    nom TEXT)"""))
            return True

        _init_journal()

        CHAMPS_CREATION = {
            "essai": ("idexper", None),
            "site": ("idsite", "nomsite"),
            "speculation": ("idspecula", "nomspeculation"),
            "type": ("idtype", "nomtype"),
            "variete": ("idvariete", "nomvariete"),
        }
        LIBELLES_CREATION = {"essai": "Essai", "site": "Site", "speculation": "Spéculation",
                             "type": "Type", "variete": "Variété"}

        def noter_creation(table, valeurs):
            try:
                cle, champ_nom = CHAMPS_CREATION[table]
                with engine.begin() as conn:
                    conn.execute(
                        text("""INSERT INTO journal_creation (idutilisateur, utilisateur_nom, type_element, code, nom)
                                VALUES (:u, :n, :t, :c, :nom)"""),
                        {"u": int(UTILISATEUR["idutilisateur"]),
                         "n": f"{UTILISATEUR['prenom']} {UTILISATEUR['nom']}",
                         "t": LIBELLES_CREATION[table], "c": str(valeurs.get(cle)),
                         "nom": str(valeurs.get(champ_nom)) if champ_nom else None})
            except Exception:
                pass

        def nettoyer_valeur(x):
            if pd.isna(x):
                return None
            if isinstance(x, (int, float)):
                return float(x)
            match = re.search(r"[-+]?\d*\.?\d+", str(x))
            return float(match.group()) if match else None

        def upsert(table, colonnes, valeurs, cle_primaire):
            placeholders = ", ".join(f":{c}" for c in colonnes)
            cols = ", ".join(colonnes)
            sql = text(f"INSERT INTO {table} ({cols}) VALUES ({placeholders}) "
                       f"ON CONFLICT ({cle_primaire}) DO NOTHING")
            with engine.begin() as conn:
                nb = conn.execute(sql, valeurs).rowcount
            if nb:
                noter_cles(table, [valeurs[cle_primaire]])
            return nb

        def inserer_nouveau(table, colonnes, valeurs, cle_primaire):
            if upsert(table, colonnes, valeurs, cle_primaire) == 0:
                raise ValueError("ce code existe déjà, rien n'a été créé.")
            noter_creation(table, valeurs)

        import io

        def modele_excel(feuilles):
            tampon = io.BytesIO()
            with pd.ExcelWriter(tampon, engine="openpyxl") as w:
                for nom, colonnes in feuilles.items():
                    pd.DataFrame(columns=colonnes).to_excel(w, sheet_name=nom, index=False)
            return tampon.getvalue()

